from itertools import combinations
# FDs implied by the ER model: keys of E1 and E2. A22 is multi-valued (A21 ->> A22 is an MVD, not an FD);
# R12 is many-to-many, so neither A11 -> A21 nor A21 -> A11 holds.
FDS = [({'A11'}, {'A12', 'A13'}), ({'A21'}, {'A23'})]
def closure(X):
    X = set(X); changed = True
    while changed:
        changed = False
        for l, r in FDS:
            if l <= X and not r <= X: X |= r; changed = True
    return X
def subsets(R):
    return [set(c) for k in range(1, len(R) + 1) for c in combinations(sorted(R), k)]
def keys(R):
    sk = [X for X in subsets(R) if R <= closure(X)]
    return [K for K in sk if not any(o < K for o in sk)]
def is_3nf(R):
    R = set(R); prime = set().union(*keys(R))
    for X in subsets(R):
        for A in (closure(X) & R) - X:          # non-trivial X -> A projected onto R
            if not (R <= closure(X) or A in prime):
                return False
    return True
standard = {'E1': {'A11', 'A12', 'A13'}, 'E2': {'A21', 'A23'},
            'E2_A22': {'A21', 'A22'}, 'R12': {'A11', 'A21'}}
for name, R in standard.items():
    print(name, sorted(R), 'keys', [sorted(k) for k in keys(R)], '3NF' if is_3nf(R) else 'NOT 3NF')
assert all(is_3nf(R) for R in standard.values()) and len(standard) == 4   # official key 4 to 4
# merges that would save a relation but break 3NF (partial dependencies on a composite key)
assert not is_3nf({'A11', 'A12', 'A13', 'A21'})    # R12 folded into E1: A11 -> A12,A13
assert not is_3nf({'A21', 'A23', 'A11'})           # R12 folded into E2: A21 -> A23
assert not is_3nf({'A21', 'A22', 'A23'})           # A22 flattened into E2: A21 -> A23
# caveat: R12 joined with the A22 table has only trivial FDs, so it passes an FD-only 3NF test,
# but it stores the cross product of partners x A22-values (MVD A21 ->> A22, a 4NF violation) and
# cannot hold an E2 entity with no A22 value; the standard mapping keeps them separate.
print('R12 x A22 merge 3NF by FDs only:', is_3nf({'A11', 'A21', 'A22'}))
